           <span>Privacy</span>
           <span>Accessibility</span>
           <span>Stanford University</span>
        </div>
      </footer>

      {/* Overlays */}
      <AICurator 
        isOpen={isAIChatOpen} 
        onClose={() => setIsAIChatOpen(false)} 
      />

      <ReadingListModal
        isOpen={isReadingListOpen}
        onClose={() => setIsReadingListOpen(false)}
        readingList={readingList}
        onRemove={toggleBook}
      />

      {/* Global Styles */}
      <style>{`
        @keyframes fadeInUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes scaleUp {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        @keyframes slideInRight {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up { animation: fadeInUp 0.6s ease-out forwards; }
        .animate-scale-up { animation: scaleUp 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        .animate-slide-in-right { animation: slideInRight 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ExhibitItem, ExhibitCategory, Book } from '../types';

interface ExhibitDetailProps {
  item: ExhibitItem;
  category: ExhibitCategory;
  onBack: () => void;
  readingList: Book[];
  onToggleBook: (book: Book) => void;
}

export const ExhibitDetail: React.FC<ExhibitDetailProps> = ({ item, category, onBack, readingList, onToggleBook }) => {
