import React, { useState } from 'react';
import { Book } from '../types';

interface ReadingListModalProps {
  isOpen: boolean;
  onClose: () => void;
  readingList: Book[];
  onRemove: (book: Book) => void;
}

export const ReadingListModal: React.FC<ReadingListModalProps> = ({ isOpen, onClose, readingList, onRemove }) => {
  const [copied, setCopied] = useState(false);

  if (!isOpen) return null;

  const formatCitations = () => {
    return readingList.map(b => {
      let citation = `${b.title} by ${b.author}`;
      if (b.publisher) citation += `, ${b.publisher}`;
      if (b.date) citation += ` (${b.date})`;
      if (b.link) citation += ` - ${b.link}`;
      return citation;
    }).join('\n\n');
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(formatCitations());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleEmail = () => {
    const subject = encodeURIComponent("My Reading List - Crown Law Digital Exhibit");
    const body = encodeURIComponent("Here is my reading list from the Crown Law Library Digital Exhibit:\n\n" + formatCitations());
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
  };

  const handleDownload = () => {
    const headers = ["Title", "Author", "Publisher", "Date", "Link"];
    const csvContent = [
      headers.join(","),
      ...readingList.map(b => [
        `"${b.title.replace(/"/g, '""')}"`,
        `"${b.author.replace(/"/g, '""')}"`,
        `"${(b.publisher || '').replace(/"/g, '""')}"`,
        `"${(b.date || '').replace(/"/g, '""')}"`,
        `"${(b.link || '').replace(/"/g, '""')}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "crown_law_reading_list.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative w-full max-w-2xl bg-white dark:bg-[#1a1a1a] rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[80vh] animate-scale-up border border-gray-200 dark:border-white/10">

        {/* Header */}
        <div className="p-6 border-b border-gray-100 dark:border-white/5 flex justify-between items-center bg-gray-50 dark:bg-[#222]">
           <div>
             <span className="text-stanford-primary text-xs font-bold uppercase tracking-widest block mb-1">Crown Law Library</span>
             <h2 className="text-2xl font-serif font-bold text-gray-900 dark:text-white">My Reading List</h2>
           </div>
           <button onClick={onClose} className="p-2 rounded-full hover:bg-gray-200 dark:hover:bg-white/10 transition-colors">
             <svg className="w-6 h-6 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
           </button>
        </div>

        {/* Instructions / Context */}
        <div className="bg-stanford-primary/5 border-b border-stanford-primary/10 p-4 text-sm text-gray-700 dark:text-gray-300">
          <div className="flex gap-3">
             <svg className="w-5 h-5 text-stanford-primary flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
             <p>
               <strong className="font-semibold block text-gray-900 dark:text-white mb-1">How to export your list:</strong>
               Review your selected books below. Use the buttons at the bottom to copy citations to your clipboard, email the list to yourself, or download a CSV file for your reference manager.
             </p>
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {readingList.length === 0 ? (
            <div className="text-center py-12">
              <div className="inline-block p-4 rounded-full bg-gray-100 dark:bg-white/5 mb-4">
                 <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
              </div>
              <p className="text-gray-500 dark:text-gray-400">Your reading list is empty.</p>
              <p className="text-sm text-gray-400 dark:text-gray-500 mt-2">Browse the exhibits and click the bookmark icon to add books.</p>
            </div>
          ) : (
            readingList.map((book, idx) => (
              <div key={idx} className="flex justify-between items-start p-4 rounded-lg bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-transparent group">
                 <div className="pr-4">
                    <h4 className="font-bold text-gray-900 dark:text-white leading-tight">{book.title}</h4>
                    <p className="text-sm text-gray-600 dark:text-gray-300 mt-1">{book.author}</p>
                    <div className="flex flex-wrap gap-2 mt-2 text-xs text-gray-500">
                      {book.publisher && <span>{book.publisher}</span>}
                      {book.date && <span>• {book.date}</span>}
                    </div>
                 </div>
                 <button 
                   onClick={() => onRemove(book)}
                   className="text-gray-400 hover:text-red-500 transition-colors p-1"
                   title="Remove from list"
                 >
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                 </button>
              </div>
            ))
          )}
        </div>

        {/* Footer */}
        {readingList.length > 0 && (
          <div className="p-6 border-t border-gray-100 dark:border-white/5 bg-gray-50 dark:bg-[#222] grid grid-cols-3 gap-3">
            <button 
              onClick={handleCopy}
              className="flex items-center justify-center gap-2 px-3 py-3 bg-white dark:bg-white/10 border border-gray-200 dark:border-white/10 rounded-lg font-semibold text-gray-900 dark:text-white hover:bg-gray-50 dark:hover:bg-white/20 transition-colors text-sm"
            >
               {copied ? (
                 <>
                   <svg className="w-4 h-4 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
                   <span>Copied!</span>
                 </>
               ) : (
                 <>
                   <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3"></path></svg>
                   <span>Copy</span>
                 </>
               )}
            </button>

            <button 
              onClick={handleDownload}
              className="flex items-center justify-center gap-2 px-3 py-3 bg-white dark:bg-white/10 border border-gray-200 dark:border-white/10 rounded-lg font-semibold text-gray-900 dark:text-white hover:bg-gray-50 dark:hover:bg-white/20 transition-colors text-sm"
            >
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
               <span>Download CSV</span>
            </button>

            <button 
              onClick={handleEmail}
              className="flex items-center justify-center gap-2 px-3 py-3 bg-stanford-primary text-white rounded-lg font-bold hover:bg-stanford-dark transition-colors shadow-lg text-sm"
            >
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"></path></svg>
               <span>Email List</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ExhibitItem, ExhibitCategory, Book } from '../types';

interface ExhibitDetailProps {
  item: ExhibitItem;
  category: ExhibitCategory;
  onBack: () => void;
  readingList: Book[];
  onToggleBook: (book: Book) => void;
}

export const ExhibitDetail: React.FC<ExhibitDetailProps> = ({ item, category, onBack, readingList, onToggleBook }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  const images = item.gallery ? item.gallery : [item.posterUrl];
  const hasMultipleImages = images.length > 1;
  const isVerticalGallery = item.galleryLayout === 'vertical';

  const nextImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setCurrentImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const isBookmarked = (book: Book) => {
    return readingList.some(b => b.title === book.title);
  };

  return (
    <div className="animate-fade-in-up w-full">
      {/* Navigation Header */}
      <div className="flex items-center mb-8">
        <button 
          onClick={onBack}
          className="group mr-6 p-3 rounded-full bg-white border border-gray-200 shadow-sm hover:bg-gray-100 dark:bg-white/5 dark:border-transparent dark:hover:bg-white/10 text-gray-900 dark:text-white transition-all hover:-translate-x-1"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
        </button>
        <div>
          <div className="flex items-center gap-2 text-stanford-primary text-xs font-bold uppercase tracking-widest mb-1">
            <span>Gallery Section</span>
            <span className="w-1 h-1 rounded-full bg-stanford-primary"></span>
            <span>{category.title}</span>
          </div>
          <h2 className="text-3xl md:text-5xl font-serif font-bold text-gray-900 dark:text-white">{item.title}</h2>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-12">
        {/* Left Column: Visuals */}
        <div className="w-full lg:w-5/12 flex flex-col gap-4">
           {isVerticalGallery ? (
             /* Vertical List Layout */
             <div className="flex flex-col gap-6">
                {images.map((img, idx) => (
                  <div key={idx} className="relative rounded-xl overflow-hidden shadow-lg border border-gray-200 dark:border-white/10 bg-gray-100 dark:bg-black/20">
                     <img 
                       src={img} 
                       alt={`${item.title} - Image ${idx + 1}`} 
                       className="w-full h-auto object-contain"
                     />
                  </div>
                ))}
             </div>
           ) : (
             /* Default Carousel Layout */
             <>
               <div className="relative rounded-xl overflow-hidden shadow-2xl bg-gray-100 dark:bg-black/40 border border-gray-200 dark:border-white/10 group">
                 <img 
                  src={images[currentImageIndex]} 
                  alt={item.title} 
                  className="w-full h-auto"
                 />

                 {/* Carousel Controls - Always Visible */}
                 {hasMultipleImages && (
                   <>
                     <button 
                       onClick={prevImage}
                       className="absolute left-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-white/90 dark:bg-black/60 text-gray-900 dark:text-white hover:bg-stanford-primary hover:text-white dark:hover:bg-stanford-primary shadow-lg transition-all"
                       aria-label="Previous image"
                     >
                       <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7"></path></svg>
                     </button>
                     <button 
                       onClick={nextImage}
                       className="absolute right-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-white/90 dark:bg-black/60 text-gray-900 dark:text-white hover:bg-stanford-primary hover:text-white dark:hover:bg-stanford-primary shadow-lg transition-all"
                       aria-label="Next image"
                     >
                       <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"></path></svg>
                     </button>

                     {/* Badge Counter */}
                     <div className="absolute bottom-4 right-4 bg-black/70 backdrop-blur-md px-3 py-1 rounded-full text-xs font-bold text-white tracking-wider border border-white/10">
                       {currentImageIndex + 1} / {images.length}
                     </div>
                   </>
                 )}
               </div>

               {/* Thumbnails Gallery */}
               {hasMultipleImages && (
                 <div className="grid grid-cols-4 gap-3">
                   {images.map((img, idx) => (
                     <button
                       key={idx}
                       onClick={() => setCurrentImageIndex(idx)}
                       className={`relative rounded-lg overflow-hidden aspect-square border-2 transition-all duration-300 ${
                         idx === currentImageIndex 
                           ? 'border-stanford-primary ring-2 ring-stanford-primary/30' 
                           : 'border-transparent opacity-60 hover:opacity-100 hover:border-gray-300 dark:hover:border-white/30'
                       }`}
                     >
                       <img 
                         src={img} 
                         alt={`Thumbnail ${idx + 1}`} 
                         className="w-full h-full object-cover"
                       />
                     </button>
                   ))}
                 </div>
               )}
             </>
           )}
        </div>

        {/* Right Column: Content */}
        <div className="w-full lg:w-7/12 space-y-10">

          {/* Featured Content Image (Large Right Side) */}
          {item.contentImage && (
            <div className="w-full rounded-xl overflow-hidden shadow-2xl border border-gray-200 dark:border-white/10 mb-8">
              <img 
                src={item.contentImage} 
                alt={`${item.title} Featured Content`}
                className="w-full h-auto object-cover"
              />
            </div>
          )}

          {/* Main Description */}
          <div>
            <h3 className="text-2xl font-light text-gray-700 dark:text-gray-200 mb-6 leading-relaxed border-l-4 border-stanford-primary pl-6">
              {item.description}
            </h3>

            {/* External Links */}
            {item.links && item.links.length > 0 && (
              <div className="mb-8 flex flex-wrap gap-4">
                {item.links.map((link, idx) => (
                  <a 
                    key={idx}
                    href={link.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center justify-center gap-2 px-6 py-3 bg-stanford-primary text-white font-bold rounded-full shadow-lg hover:bg-stanford-dark transition-all transform hover:-translate-y-1 hover:shadow-xl group"
                  >
                    <span>{link.title}</span>
                    <svg className="w-5 h-5 group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"></path></svg>
                  </a>
                ))}
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {item.details.map((detail, idx) => (
                <div key={idx} className="flex items-start p-4 rounded-lg bg-white border border-gray-200 shadow-sm dark:bg-white/5 dark:border-white/5 dark:shadow-none">
                  <span className="flex-shrink-0 w-2 h-2 rounded-full bg-stanford-primary mt-2 mr-3"></span>
                  <span className="text-gray-600 dark:text-gray-300 leading-relaxed text-sm">{detail}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Video Section */}
          {item.videoUrl && (
            <div className="space-y-4">
              <h4 className="text-gray-900 dark:text-white font-bold text-sm uppercase tracking-wider flex items-center gap-2 border-b border-gray-200 dark:border-white/10 pb-2">
                <svg className="w-5 h-5 text-stanford-primary" fill="currentColor" viewBox="0 0 24 24"><path d="M19.615 3.184c-3.604-.246-11.631-.245-15.23 0-3.897.266-4.356 2.62-4.385 8.816.029 6.185.484 8.549 4.385 8.816 3.6.245 11.626.246 15.23 0 3.897-.266 4.356-2.62 4.385-8.816-.029-6.185-.484-8.549-4.385-8.816zm-10.615 12.816v-8l8 3.993-8 4.007z"/></svg>
                Video Preview
              </h4>
              <div className="relative w-full pt-[56.25%] rounded-xl overflow-hidden border border-gray-200 dark:border-white/10 bg-black shadow-lg">
                <iframe 
                  src={item.videoUrl} 
                  className="absolute top-0 left-0 w-full h-full" 
                  allow="autoplay; fullscreen"
                  allowFullScreen
                ></iframe>
              </div>
            </div>
          )}

          {/* Books Section */}
          {item.books && (
            <div className="space-y-4">
              <div className="flex justify-between items-end border-b border-gray-200 dark:border-white/10 pb-2">
                <h4 className="text-gray-900 dark:text-white font-bold text-sm uppercase tracking-wider flex items-center gap-2">
                  <svg className="w-5 h-5 text-stanford-primary" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
                  Display Books
                </h4>
                <span className="text-[10px] text-gray-500 font-medium hidden sm:block">
                  Bookmark to export list <span className="text-stanford-primary">↗</span>
                </span>
              </div>

              <div className="grid grid-cols-1 gap-3">
                {item.books.map((book, idx) => {
                  const bookmarked = isBookmarked(book);
                  return (
                    <div 
                      key={idx} 
                      className="relative group/book p-4 rounded-lg bg-white border border-gray-200 hover:border-stanford-primary/30 dark:bg-white/5 dark:border-transparent dark:hover:bg-white/10 transition-all hover:shadow-lg flex items-start gap-4"
                    >
                      {/* Book Content - Clickable if link exists */}
                      <div 
                        className={`flex-1 ${book.link ? 'cursor-pointer' : ''}`}
                        onClick={() => book.link && window.open(book.link, '_blank')}
                      >
                        <div className="flex justify-between items-start gap-2">
                          <div className="text-gray-900 dark:text-white text-base font-bold leading-tight group-hover/book:text-stanford-primary transition-colors">
                            {book.title}
                          </div>
                          {book.date && (
                            <span className="text-[10px] bg-gray-100 text-gray-500 dark:bg-white/10 dark:text-gray-400 px-2 py-1 rounded whitespace-nowrap font-medium">
                              {book.date}
                            </span>
                          )}
                        </div>

                        <div className="text-gray-600 dark:text-gray-400 text-sm mt-1">{book.author}</div>

                        <div className="flex justify-between items-end mt-2 pt-2 border-t border-gray-100 dark:border-white/5">
                          <div className="text-[10px] text-gray-500 dark:text-gray-500 uppercase tracking-wide font-semibold">
                            {book.publisher}
                          </div>
                          {book.link && (
                            <div className="text-xs text-stanford-primary flex items-center gap-1 opacity-60 group-hover/book:opacity-100 transition-opacity font-medium">
                              <span>Catalog Record</span>
                              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3"></path></svg>
                            </div>
                          )}
                        </div>
                      </div>

                      {/* Bookmark Button */}
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          onToggleBook(book);
                        }}
                        className={`p-2 rounded-full transition-all duration-300 ${
                          bookmarked 
                            ? 'text-stanford-primary bg-red-50 dark:bg-stanford-primary/20 scale-110' 
                            : 'text-gray-300 hover:text-stanford-primary hover:bg-gray-100 dark:hover:bg-white/10 dark:text-gray-600'
                        }`}
                        title={bookmarked ? "Remove from reading list" : "Add to reading list"}
                      >
                         <svg className={`w-6 h-6 ${bookmarked ? 'fill-current' : 'fill-none'}`} stroke="currentColor" viewBox="0 0 24 24">
                           <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
                         </svg>
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { jsPDF } from 'jspdf';
import { Book } from '../types';

interface ReadingListModalProps {
  isOpen: boolean;
  onClose: () => void;
  readingList: Book[];
  onRemove: (book: Book) => void;
}

export const ReadingListModal: React.FC<ReadingListModalProps> = ({ isOpen, onClose, readingList, onRemove }) => {
  const [copied, setCopied] = useState(false);

  if (!isOpen) return null;

  const formatCitations = () => {
    return readingList.map(b => {
      let citation = `${b.title} by ${b.author}`;
      if (b.publisher) citation += `, ${b.publisher}`;
      if (b.date) citation += ` (${b.date})`;
      if (b.link) citation += ` - ${b.link}`;
      return citation;
    }).join('\n\n');
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(formatCitations());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleEmail = () => {
    const subject = encodeURIComponent("My Reading List - Crown Law Digital Exhibit");
    const body = encodeURIComponent("Here is my reading list from the Crown Law Library Digital Exhibit:\n\n" + formatCitations());
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
  };

  const handleDownloadPDF = () => {
    const doc = new jsPDF();

    // Title
    doc.setFont("times", "bold");
    doc.setFontSize(22);
    doc.setTextColor(140, 21, 21); // Stanford Red
    doc.text("Crown Law Library", 20, 20);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(14);
    doc.setTextColor(60, 60, 60);
    doc.text("Digital Exhibit Reading List", 20, 30);

    doc.setLineWidth(0.5);
    doc.setDrawColor(200, 200, 200);
    doc.line(20, 35, 190, 35);

    let y = 50;
    const pageHeight = doc.internal.pageSize.height;

    readingList.forEach((book) => {
      // Check if we need a new page
      if (y > pageHeight - 40) {
        doc.addPage();
        y = 30;
      }

      // Book Title
      doc.setFont("helvetica", "bold");
      doc.setFontSize(12);
      doc.setTextColor(0, 0, 0);
      const titleLines = doc.splitTextToSize(book.title, 170);
      doc.text(titleLines, 20, y);
      y += 6 * titleLines.length;

      // Author
      doc.setFont("helvetica", "normal");
      doc.setFontSize(11);
      doc.setTextColor(50, 50, 50);
      doc.text(`By ${book.author}`, 20, y);
      y += 6;

      // Details
      let details = "";
      if (book.publisher) details += book.publisher;
      if (book.date) details += details ? `, ${book.date}` : book.date;

      if (details) {
        doc.setFontSize(10);
        doc.setTextColor(100, 100, 100);
        doc.text(details, 20, y);
        y += 6;
      }

      // Link
      if (book.link) {
        doc.setTextColor(0, 0, 255);
        doc.setFontSize(10);
        doc.textWithLink("View Catalog Record", 20, y, { url: book.link });
        y += 6;
      }

      y += 8; // Spacer
    });

    // Footer
    const today = new Date().toLocaleDateString();
    doc.setFontSize(9);
    doc.setTextColor(150, 150, 150);
    doc.text(`Generated on ${today}`, 20, pageHeight - 10);

    doc.save("Crown_Law_Reading_List.pdf");
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative w-full max-w-2xl bg-white dark:bg-[#1a1a1a] rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[80vh] animate-scale-up border border-gray-200 dark:border-white/10">

        {/* Header */}
        <div className="p-6 border-b border-gray-100 dark:border-white/5 flex justify-between items-center bg-gray-50 dark:bg-[#222]">
           <div>
             <span className="text-stanford-primary text-xs font-bold uppercase tracking-widest block mb-1">Crown Law Library</span>
             <h2 className="text-2xl font-serif font-bold text-gray-900 dark:text-white">My Reading List</h2>
           </div>
           <button onClick={onClose} className="p-2 rounded-full hover:bg-gray-200 dark:hover:bg-white/10 transition-colors">
             <svg className="w-6 h-6 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
           </button>
        </div>

        {/* Instructions / Context */}
        <div className="bg-stanford-primary/5 border-b border-stanford-primary/10 p-4 text-sm text-gray-700 dark:text-gray-300">
          <div className="flex gap-3">
             <svg className="w-5 h-5 text-stanford-primary flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
             <p>
               <strong className="font-semibold block text-gray-900 dark:text-white mb-1">How to export your list:</strong>
               Review your selected books below. You can copy the citations, download a formatted PDF, or email the list to yourself.
             </p>
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {readingList.length === 0 ? (
            <div className="text-center py-12">
              <div className="inline-block p-4 rounded-full bg-gray-100 dark:bg-white/5 mb-4">
                 <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
              </div>
              <p className="text-gray-500 dark:text-gray-400">Your reading list is empty.</p>
              <p className="text-sm text-gray-400 dark:text-gray-500 mt-2">Browse the exhibits and click the bookmark icon to add books.</p>
            </div>
          ) : (
            readingList.map((book, idx) => (
              <div key={idx} className="flex justify-between items-start p-4 rounded-lg bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-transparent group">
                 <div className="pr-4">
                    <h4 className="font-bold text-gray-900 dark:text-white leading-tight">{book.title}</h4>
                    <p className="text-sm text-gray-600 dark:text-gray-300 mt-1">{book.author}</p>
                    <div className="flex flex-wrap gap-2 mt-2 text-xs text-gray-500">
                      {book.publisher && <span>{book.publisher}</span>}
                      {book.date && <span>• {book.date}</span>}
                    </div>
                 </div>
                 <button 
                   onClick={() => onRemove(book)}
                   className="text-gray-400 hover:text-red-500 transition-colors p-1"
                   title="Remove from list"
                 >
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                 </button>
              </div>
            ))
          )}
        </div>

        {/* Footer */}
        {readingList.length > 0 && (
          <div className="p-6 border-t border-gray-100 dark:border-white/5 bg-gray-50 dark:bg-[#222] grid grid-cols-3 gap-3">
            <button 
              onClick={handleCopy}
              className="flex items-center justify-center gap-2 px-3 py-3 bg-white dark:bg-white/10 border border-gray-200 dark:border-white/10 rounded-lg font-semibold text-gray-900 dark:text-white hover:bg-gray-50 dark:hover:bg-white/20 transition-colors text-sm"
            >
               {copied ? (
                 <>
                   <svg className="w-4 h-4 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
                   <span>Copied!</span>
                 </>
               ) : (
                 <>
                   <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3"></path></svg>
                   <span>Copy</span>
                 </>
               )}
            </button>

            <button 
              onClick={handleDownloadPDF}
              className="flex items-center justify-center gap-2 px-3 py-3 bg-white dark:bg-white/10 border border-gray-200 dark:border-white/10 rounded-lg font-semibold text-gray-900 dark:text-white hover:bg-gray-50 dark:hover:bg-white/20 transition-colors text-sm"
            >
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
               <span>Save PDF</span>
            </button>

            <button 
              onClick={handleEmail}
              className="flex items-center justify-center gap-2 px-3 py-3 bg-stanford-primary text-white rounded-lg font-bold hover:bg-stanford-dark transition-colors shadow-lg text-sm"
            >
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"></path></svg>
               <span>Email List</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ExhibitItem, ExhibitCategory, Book } from '../types';

interface ExhibitDetailProps {
  item: ExhibitItem;
  category: ExhibitCategory;
  onBack: () => void;
  readingList: Book[];
  onToggleBook: (book: Book) => void;
}

export const ExhibitDetail: React.FC<ExhibitDetailProps> = ({ item, category, onBack, readingList, onToggleBook }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  const images = item.gallery ? item.gallery : [item.posterUrl];
  const hasMultipleImages = images.length > 1;
  const isVerticalGallery = item.galleryLayout === 'vertical';

  const nextImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setCurrentImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const isBookmarked = (book: Book) => {
    return readingList.some(b => b.title === book.title);
  };

  return (
    <div className="animate-fade-in-up w-full">
      {/* Navigation Header */}
      <div className="flex items-center mb-8">
        <button 
          onClick={onBack}
          className="group mr-6 p-3 rounded-full bg-white border border-gray-200 shadow-sm hover:bg-gray-100 dark:bg-white/5 dark:border-transparent dark:hover:bg-white/10 text-gray-900 dark:text-white transition-all hover:-translate-x-1"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
        </button>
        <div>
          <div className="flex items-center gap-2 text-stanford-primary text-xs font-bold uppercase tracking-widest mb-1">
            <span>Gallery Section</span>
            <span className="w-1 h-1 rounded-full bg-stanford-primary"></span>
            <span>{category.title}</span>
          </div>
          <h2 className="text-3xl md:text-5xl font-serif font-bold text-gray-900 dark:text-white">{item.title}</h2>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-12">
        {/* Left Column: Visuals */}
        <div className="w-full lg:w-5/12 flex flex-col gap-4">
           {isVerticalGallery ? (
             /* Vertical List Layout */
             <div className="flex flex-col gap-6">
                {images.map((img, idx) => (
                  <div key={idx} className="relative rounded-xl overflow-hidden shadow-lg border border-gray-200 dark:border-white/10 bg-gray-100 dark:bg-black/20">
                     <img 
                       src={img} 
                       alt={`${item.title} - Image ${idx + 1}`} 
                       className="w-full h-auto object-contain"
                     />
                  </div>
                ))}
             </div>
           ) : (
             /* Default Carousel Layout */
             <>
               <div className="relative rounded-xl overflow-hidden shadow-2xl bg-gray-100 dark:bg-black/40 border border-gray-200 dark:border-white/10 group">
                 <img 
                  src={images[currentImageIndex]} 
                  alt={item.title} 
                  className="w-full h-auto"
                 />

                 {/* Carousel Controls - Always Visible */}
