                          <div className="text-gray-900 dark:text-white text-base font-bold leading-tight group-hover/book:text-stanford-primary transition-colors line-clamp-2">
                            {book.title}
                          </div>
                          {book.date && (
                            <span className="text-[10px] bg-gray-100 text-gray-500 dark:bg-white/10 dark:text-gray-400 px-2 py-1 rounded whitespace-nowrap font-medium flex-shrink-0">
                              {book.date}
                            </span>
                          )}
                        </div>

                        <div className="text-gray-600 dark:text-gray-400 text-sm mt-1 truncate">{book.author}</div>

                        <div className="flex justify-between items-end mt-2 pt-2 border-t border-gray-100 dark:border-white/5">
                          <div className="text-[10px] text-gray-500 dark:text-gray-500 uppercase tracking-wide font-semibold truncate pr-2">
                            {book.publisher}
                          </div>
                          {book.link && (
                            <div className="text-xs text-stanford-primary flex items-center gap-1 opacity-60 group-hover/book:opacity-100 transition-opacity font-medium flex-shrink-0">
                              <span>Catalog Record</span>
                              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3"></path></svg>
                            </div>
                          )}
                        </div>
                      </div>

                      {/* Bookmark Button */}
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          onToggleBook(book);
                        }}
                        className={`p-2 rounded-full transition-all duration-300 flex-shrink-0 ${
                          bookmarked 
                            ? 'text-stanford-primary bg-red-50 dark:bg-stanford-primary/20 scale-110' 
                            : 'text-gray-300 hover:text-stanford-primary hover:bg-gray-100 dark:hover:bg-white/10 dark:text-gray-600'
                        }`}
                        title={bookmarked ? "Remove from reading list" : "Add to reading list"}
                      >
                         <svg className={`w-6 h-6 ${bookmarked ? 'fill-current' : 'fill-none'}`} stroke="currentColor" viewBox="0 0 24 24">
                           <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
                         </svg>
                      </button>
                    </div>
                  );
                })}
              </div>

              {/* Attribution for Open Library */}
              <div className="text-center mt-4">
                 <p className="text-[10px] text-gray-400 dark:text-gray-600">
                    Book covers provided by <a href="https://openlibrary.org/" target="_blank" rel="noopener noreferrer" className="hover:text-stanford-primary transition-colors">Open Library</a> API
                 </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

