                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
              </span>
              Display Books
            </h4>
            {category.id === 'reading' && (
              <span className="text-xs md:text-sm text-gray-500 dark:text-gray-400 font-medium">
                Bookmark items to export your reading list <span className="text-stanford-primary dark:text-red-400 font-bold ml-1">↗</span>
              </span>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {item.books.map((book, idx) => {
              const bookmarked = isBookmarked(book);
              const coverUrl = book.isbn ? `https://covers.openlibrary.org/b/isbn/${book.isbn}-M.jpg` : null;

              return (
                <div 
                  key={idx} 
                  className="relative group/book p-5 rounded-xl bg-white border border-gray-200 hover:border-stanford-primary/50 hover:ring-2 hover:ring-stanford-primary/10 dark:bg-white/5 dark:border-white/10 dark:hover:border-stanford-primary/50 transition-all hover:shadow-xl hover:-translate-y-1 flex items-start gap-5 h-full"
                >
                  {/* Book Cover */}
                  <div className="flex-shrink-0 w-20 h-28 bg-gray-100 dark:bg-black/20 rounded-md overflow-hidden shadow-md relative border border-gray-200 dark:border-white/5 group-hover/book:shadow-lg transition-all">
                    {coverUrl && (
                      <img
                        src={coverUrl}
                        alt={`Cover of ${book.title}`}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          e.currentTarget.style.display = 'none';
                          const nextSibling = e.currentTarget.nextElementSibling;
                          if (nextSibling) {
                            nextSibling.classList.remove('hidden');
                          }
                        }}
                      />
                    )}
                    {/* Fallback Icon */}
                    <div className={`absolute inset-0 flex items-center justify-center text-gray-300 dark:text-gray-600 ${coverUrl ? 'hidden' : ''}`}>
                       <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
                    </div>
                  </div>

                  {/* Book Content */}
                  <div className="flex-1 min-w-0 flex flex-col h-full">
                    <div className="flex justify-between items-start gap-2 mb-1">
                      <div 
                        className={`text-gray-900 dark:text-white text-lg font-bold leading-tight group-hover/book:text-stanford-primary transition-colors line-clamp-2 ${book.link ? 'cursor-pointer' : ''}`}
                        onClick={() => book.link && window.open(book.link, '_blank')}
                      >
                        {book.title}
                      </div>
                      {book.date && (
                        <span className="text-[10px] uppercase tracking-wide bg-gray-100 text-gray-600 dark:bg-white/10 dark:text-gray-300 px-2 py-1 rounded-sm font-bold flex-shrink-0">
                          {book.date.split(' ').pop()} {/* Show just year if space limited, but keeping full for now */}
                        </span>
                      )}
                    </div>

                    <div className="text-gray-600 dark:text-gray-300 text-sm font-medium mb-auto">{book.author}</div>

                    <div className="pt-3 mt-2 border-t border-gray-100 dark:border-white/5 flex flex-col gap-2">
                      <div className="text-xs text-gray-500 dark:text-gray-500 uppercase tracking-wide font-semibold truncate">
                        {book.publisher}
                      </div>

                      {book.link && (
                        <div className="flex justify-start">
                          <a 
                            href={book.link} 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-stanford-primary/10 text-stanford-primary text-xs font-bold uppercase tracking-wider hover:bg-stanford-primary hover:text-white transition-all group/link"
                          >
                            <span>Catalog Record</span>
                            <svg className="w-3 h-3 group-hover/link:translate-x-0.5 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3"></path></svg>
                          </a>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Bookmark Button */}
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      onToggleBook(book);
                    }}
                    className={`absolute top-4 right-4 p-2 rounded-full transition-all duration-300 shadow-sm ${
                      bookmarked 
                        ? 'text-white bg-stanford-primary scale-110 shadow-md' 
                        : 'text-gray-300 bg-white/80 dark:bg-black/40 hover:text-stanford-primary hover:bg-white dark:hover:bg-white/20 dark:text-gray-400'
                    }`}
                    title={bookmarked ? "Remove from reading list" : "Add to reading list"}
                  >
                     <svg className={`w-5 h-5 ${bookmarked ? 'fill-current' : 'fill-none'}`} stroke="currentColor" viewBox="0 0 24 24">
                       <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
                     </svg>
                  </button>
                </div>
              );
            })}
          </div>

          <div className="text-center mt-8">
             <p className="text-xs text-gray-400 dark:text-gray-600 flex items-center justify-center gap-2">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                Book covers provided by <a href="https://openlibrary.org/" target="_blank" rel="noopener noreferrer" className="hover:text-stanford-primary transition-colors underline decoration-dotted">Open Library API</a>
             </p>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { EXHIBIT_CATEGORIES } from './constants';
