               <div className="relative">
                  <svg className="w-5 h-5 text-gray-600 dark:text-gray-300 group-hover:text-stanford-primary transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01"></path></svg>
                  {readingList.length > 0 && (
                    <span className="absolute -top-2 -right-2 w-4 h-4 flex items-center justify-center bg-stanford-primary text-white text-[9px] font-bold rounded-full shadow-sm animate-scale-up">
                      {readingList.length}
                    </span>
                  )}
               </div>
               <span className="font-semibold text-sm text-gray-800 dark:text-white">View & Export List</span>
               <span className="text-gray-400 group-hover:text-stanford-primary transition-colors">→</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {item.books.map((book, idx) => {
              const bookmarked = isBookmarked(book);
              // Adding ?default=false to ensure 404 on missing images so onError triggers
              const coverUrl = book.isbn ? `https://covers.openlibrary.org/b/isbn/${book.isbn}-M.jpg?default=false` : null;

              return (
                <div 
                  key={idx} 
                  className="relative group/book p-5 rounded-xl bg-white border border-gray-200 hover:border-stanford-primary/50 hover:ring-2 hover:ring-stanford-primary/10 dark:bg-white/5 dark:border-white/10 dark:hover:border-stanford-primary/50 transition-all hover:shadow-xl hover:-translate-y-1 flex items-start gap-5 h-full"
                >
                  {/* Book Cover */}
                  <div className="flex-shrink-0 w-24 h-36 bg-gray-100 dark:bg-black/20 rounded-md overflow-hidden shadow-md relative border border-gray-200 dark:border-white/5 group-hover/book:shadow-lg transition-all">
                    {coverUrl && (
                      <img
                        src={coverUrl}
                        alt={`Cover of ${book.title}`}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          e.currentTarget.style.display = 'none';
                          const nextSibling = e.currentTarget.nextElementSibling;
                          if (nextSibling) {
                            nextSibling.classList.remove('hidden');
                          }
                        }}
                      />
                    )}
                    {/* Fallback Icon */}
                    <div className={`absolute inset-0 flex flex-col items-center justify-center text-gray-300 dark:text-gray-600 p-2 text-center bg-gray-50 dark:bg-white/5 ${coverUrl ? 'hidden' : ''}`}>
                       <svg className="w-8 h-8 mb-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
                       <span className="text-[9px] uppercase font-bold tracking-wider opacity-60">No Cover</span>
                    </div>
                  </div>

                  {/* Book Content */}
                  <div className="flex-1 min-w-0 flex flex-col h-full">
                    <div className="flex justify-between items-start gap-2 mb-1">
                      <div 
                        className={`text-gray-900 dark:text-white text-lg font-bold leading-tight group-hover/book:text-stanford-primary transition-colors line-clamp-2 ${book.link ? 'cursor-pointer' : ''}`}
                        onClick={() => book.link && window.open(book.link, '_blank')}
                      >
                        {book.title}
                      </div>
                    </div>

                    <div className="text-gray-600 dark:text-gray-300 text-sm font-medium mb-auto">{book.author}</div>

                    <div className="pt-3 mt-3 border-t border-gray-100 dark:border-white/5 flex flex-col gap-2">
                       <div className="flex flex-wrap gap-2 text-[10px] text-gray-500 dark:text-gray-400 font-medium">
                          <span className="uppercase tracking-wide font-bold">{book.publisher}</span>
                          {book.date && <span>• {book.date.split(' ').pop()}</span>}
                       </div>

                      {book.link && (
                        <div className="flex justify-start mt-1">
                          <a 
                            href={book.link} 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-stanford-primary/10 text-stanford-primary text-xs font-bold uppercase tracking-wider hover:bg-stanford-primary hover:text-white transition-all group/link w-full justify-center"
                          >
                            <span>Catalog Record</span>
                            <svg className="w-3 h-3 group-hover/link:translate-x-0.5 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3"></path></svg>
                          </a>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Bookmark Button */}
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      onToggleBook(book);
                    }}
                    className={`absolute top-4 right-4 p-2 rounded-full transition-all duration-300 shadow-sm z-10 ${
                      bookmarked 
                        ? 'text-white bg-stanford-primary scale-110 shadow-md' 
                        : 'text-gray-300 bg-white/80 dark:bg-black/60 hover:text-stanford-primary hover:bg-white dark:hover:bg-white/20 dark:text-gray-400 backdrop-blur-sm'
                    }`}
                    title={bookmarked ? "Remove from reading list" : "Add to reading list"}
                  >
                     <svg className={`w-5 h-5 ${bookmarked ? 'fill-current' : 'fill-none'}`} stroke="currentColor" viewBox="0 0 24 24">
                       <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
                     </svg>
                  </button>
                </div>
              );
            })}
          </div>

          <div className="text-center mt-8">
             <p className="text-xs text-gray-400 dark:text-gray-600 flex items-center justify-center gap-2">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                Book covers provided by <a href="https://openlibrary.org/" target="_blank" rel="noopener noreferrer" className="hover:text-stanford-primary transition-colors underline decoration-dotted">Open Library API</a>
             </p>
          </div>
        </div>
      )}
    </div>
  );
};

export interface Book {
  title: string;
  author: string;
  publisher?: string;
  date?: string;
  link?: string;
  isbn?: string;
  description?: string;
}

export interface ExhibitItem {
  id: string;
  title: string;
  subtitle: string;
  description: string;
  details: string[]; // Bullet points of content
  posterUrl: string; // Main display image
  gallery?: string[]; // Additional images for the modal
  galleryLayout?: 'carousel' | 'vertical'; // Layout mode for the gallery
  contentImage?: string; // Optional large image to display in the content area (right side)
  videoUrl?: string; // Optional embed URL for video content
  books?: Book[]; // Optional list of display books
  icon: string;
  links?: { title: string; url: string }[]; // Optional list of external links
}

export interface ExhibitCategory {
  id: string;
  title: string;
  subtitle: string;
  description: string;
  coverImage: string;
  items: ExhibitItem[];
  link?: { title: string; url: string };
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  isThinking?: boolean;
}

import React, { useState } from 'react';
import { ExhibitItem, ExhibitCategory, Book } from '../types';

interface ExhibitDetailProps {
  item: ExhibitItem;
  category: ExhibitCategory;
  onBack: () => void;
  readingList: Book[];
  onToggleBook: (book: Book) => void;
  onOpenReadingList: () => void;
}

export const ExhibitDetail: React.FC<ExhibitDetailProps> = ({ item, category, onBack, readingList, onToggleBook, onOpenReadingList }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  const images = item.gallery ? item.gallery : [item.posterUrl];
  const hasMultipleImages = images.length > 1;
  const isVerticalGallery = item.galleryLayout === 'vertical';

  const nextImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setCurrentImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const isBookmarked = (book: Book) => {
    return readingList.some(b => b.title === book.title);
  };

  return (
    <div className="animate-fade-in-up w-full">
      {/* Navigation Header */}
      <div className="flex items-center mb-8">
        <button 
          onClick={onBack}
